com.mirth.connect.plugins.javascriptstep.script:
// ADT^A01 (admit) -> FHIR R4 transaction Bundle.
//
// The clinical content is a Patient (PID) and an Encounter (PV1), each written
// with a conditional update keyed on its business identifier, so replaying a
// message updates instead of duplicating.
//
// Around it sits the record of the message itself: a MessageHeader (MSH) and
// three Provenance resources, one for where the message came from (MSH), one
// for this transformation, and one for the event (EVN). The original v2
// message is kept as a DocumentReference that the Provenance points back to.
// Those are created fresh for every message received, replays included.
//
// Mappings follow the HL7 v2-to-FHIR IG's ADT_A01 message map and its segment
// maps, trimmed to the fields Simulated Hospital fills. The bundle goes to the
// channel map as "fhirBundle"; the HTTP Sender posts it to the FHIR server.

// ---- Configuration -----------------------------------------------------------

// Identifier systems, keyed by the v2 assigning authority (CX.4 / XCN.9).
var ID_SYSTEMS = {
	'SIMULATOR MRN': 'http://simhospital.example.org/fhir/sid/mrn',
	'NHSNBR': 'https://fhir.nhs.uk/Id/nhs-number',
	'DRNBR': 'http://simhospital.example.org/fhir/sid/doctor-number'
};
// Simulated Hospital leaves PV1-19's assigning authority empty.
var VISIT_SYSTEM = 'http://simhospital.example.org/fhir/sid/visit-number';
// Namespace for v2 application and facility names (HD.1), used to identify
// the sending and receiving Organizations.
var HD_SYSTEM = 'http://simhospital.example.org/fhir/sid/v2-namespace';
// MSH-10 control IDs are unique per sender, so the system names the sender.
var CONTROL_ID_SYSTEM = 'http://simhospital.example.org/fhir/sid/v2-message-control-id';
// This channel, as the Device that performs the transformation.
var TRANSFORMER_SYSTEM = 'urn:v2fhirlab:oie-channel';

// v2 timestamps without an offset are local to the sending system. FHIR needs
// an offset on every dateTime that has a time, so we supply the sender's zone.
var SOURCE_TZ = String(java.lang.System.getenv('SOURCE_TIMEZONE') || 'UTC');

// ---- Code maps ------------------------------------------------------------------
// v2 table -> FHIR code. Where Simulated Hospital writes a word instead of the
// table code (HOME for H or PRN), the word is mapped too and marked "SH".

var GENDER = { F: 'female', M: 'male', O: 'other', A: 'other', U: 'unknown', N: 'unknown' }; // 0001

var NAME_USE = { L: 'official', D: 'usual', M: 'maiden', N: 'nickname', A: 'anonymous' }; // 0200

var ADDRESS_USE = { H: 'home', HOME: 'home' /* SH */, B: 'work', O: 'work', C: 'temp', BA: 'old' }; // 0190

var TELECOM_USE = { PRN: 'home', ORN: 'home', VHN: 'home', HOME: 'home' /* SH */, WPN: 'work' }; // 0201

var IDENTIFIER_TYPE = { MR: 'MR', MRN: 'MR' /* SH */ }; // 0203

// 0004 patient class -> v3 ActCode. Encounter.class is required.
var ENCOUNTER_CLASS = {
	E: { code: 'EMER', display: 'emergency' },
	I: { code: 'IMP', display: 'inpatient encounter' },
	O: { code: 'AMB', display: 'ambulatory' },
	P: { code: 'PRENC', display: 'pre-admission' }
};

// ---- Helpers ----------------------------------------------------------------------

// Component n of a field (PID.3 -> PID.3.n) as a string, or undefined if empty.
// A component with subcomponents yields its first subcomponent.
function comp(field, n) {
	var c = field[field.name().toString() + '.' + n];
	if (c.length() === 0) return undefined;
	if (c.hasComplexContent()) c = c.children()[0];
	var s = c.toString();
	return s === '' ? undefined : s;
}

// Every repetition of a field as an array of E4X nodes.
function reps(field) {
	var out = [];
	for (var i = 0; i < field.length(); i++) out.push(field[i]);
	return out;
}

// v2 DTM -> FHIR date or dateTime, keeping the precision the sender gave.
function fhirDateTime(dtm) {
	var m = /^(\d{4})(\d{2})?(\d{2})?(\d{2})?(\d{2})?(\d{2})?(?:\.(\d{1,4}))?([+-]\d{4})?$/.exec(dtm || '');
	if (!m) return undefined;
	var date = m[1] + (m[2] ? '-' + m[2] + (m[3] ? '-' + m[3] : '') : '');
	if (!m[4]) return date;
	var local = date + 'T' + m[4] + ':' + (m[5] || '00') + ':' + (m[6] || '00') + (m[7] ? '.' + m[7] : '');
	if (m[8]) return local + m[8].substr(0, 3) + ':' + m[8].substr(3);
	var zoned = java.time.LocalDateTime.parse(local).atZone(java.time.ZoneId.of(SOURCE_TZ));
	return String(zoned.format(java.time.format.DateTimeFormatter.ISO_OFFSET_DATE_TIME));
}

// v2 DTM -> FHIR date (drops any time, e.g. Simulated Hospital's 000000 birth time).
function fhirDate(dtm) {
	return dtm ? fhirDateTime(dtm.substr(0, 8)) : undefined;
}

function systemFor(authority) {
	if (!authority) return undefined;
	if (ID_SYSTEMS[authority]) return ID_SYSTEMS[authority];
	logger.warn('No identifier system configured for assigning authority "' + authority + '"');
	return 'urn:v2fhirlab:assigning-authority:' + encodeURIComponent(authority);
}

// Drop empty strings, nulls, empty arrays and empty objects, recursively, so the
// FHIR server never sees an element without a value.
function compact(value) {
	if (Array.isArray(value)) {
		var arr = value.map(compact).filter(function(v) { return v !== undefined; });
		return arr.length ? arr : undefined;
	}
	if (value !== null && typeof value === 'object') {
		var obj = {}, any = false;
		for (var k in value) {
			var v = compact(value[k]);
			if (v !== undefined) { obj[k] = v; any = true; }
		}
		return any ? obj : undefined;
	}
	return value === '' || value === null ? undefined : value;
}

function conditionalUrl(resourceType, identifier) {
	return resourceType + '?identifier=' + encodeURIComponent(identifier.system + '|' + identifier.value);
}

function base64(text) {
	return String(java.util.Base64.getEncoder().encodeToString(new java.lang.String(text).getBytes('UTF-8')));
}

// Bundle entries, in the order they're added. Each gets a urn:uuid fullUrl that
// other entries reference; the FHIR server swaps in real ids when it stores them.
var entries = [];
function addEntry(resource, request) {
	var fullUrl = 'urn:uuid:' + UUIDGenerator.getUUID();
	entries.push({ fullUrl: fullUrl, resource: resource, request: request });
	return fullUrl;
}
// Reference data (Organizations, the transformer Device): create it the first
// time it's seen, and leave it alone after that.
function addOnce(resource) {
	var id = resource.identifier[0];
	return addEntry(resource, {
		method: 'POST',
		url: resource.resourceType,
		ifNoneExist: 'identifier=' + encodeURIComponent(id.system + '|' + id.value)
	});
}

// HD (hierarchic designator) -> Organization, per the IG's HD[Organization] map:
// HD.1 namespace ID, plus HD.2/HD.3 universal ID when the sender gives one.
function hdOrganization(hd) {
	var universalId = comp(hd, 2), idType = comp(hd, 3);
	return {
		resourceType: 'Organization',
		identifier: [
			{ system: HD_SYSTEM, value: comp(hd, 1) },
			universalId && {
				type: idType && { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/v2-0301', code: idType }] },
				system: idType === 'ISO' || idType === 'UUID' ? 'urn:ietf:rfc:3986' : undefined,
				value: idType === 'ISO' ? 'urn:oid:' + universalId : idType === 'UUID' ? 'urn:uuid:' + universalId : universalId
			}
		]
	};
}

// HD -> MessageHeader source/destination endpoint, per the IG's
// HD[MessageHeader.*-endpoint] maps. endpoint is required, so with no
// universal ID it carries a data-absent-reason instead of a value.
var ENDPOINT_PREFIX = { ISO: 'urn:oid:', UUID: 'urn:uuid:', DNS: 'urn:dns:', URI: 'urn:uri:' };
function setEndpoint(target, hd) {
	var prefix = ENDPOINT_PREFIX[comp(hd, 3)];
	if (prefix && comp(hd, 2)) {
		target.endpoint = prefix + comp(hd, 2);
	} else {
		target._endpoint = { extension: [{ url: 'http://hl7.org/fhir/StructureDefinition/data-absent-reason', valueCode: 'unknown' }] };
	}
	return target;
}

// XCN (person) -> Reference by identifier: 1 id, 2 family, 3 given, 6 prefix,
// 9 assigning authority. Practitioner resources come later.
function xcnReference(xcn) {
	return {
		identifier: { system: systemFor(comp(xcn, 9)), value: comp(xcn, 1) },
		display: [comp(xcn, 6), comp(xcn, 3), comp(xcn, 2)].filter(Boolean).join(' ')
	};
}

var PARTICIPANT_TYPE = 'http://terminology.hl7.org/CodeSystem/provenance-participant-type';

// ---- PID -> Patient -------------------------------------------------------------

var pid = msg['PID'];

// PID-3 patient identifier list (CX): 1 value, 4 assigning authority, 5 type.
var identifiers = reps(pid['PID.3']).map(function(cx) {
	var type = comp(cx, 5);
	return {
		type: type && {
			coding: IDENTIFIER_TYPE[type] && [{ system: 'http://terminology.hl7.org/CodeSystem/v2-0203', code: IDENTIFIER_TYPE[type] }],
			text: type
		},
		system: systemFor(comp(cx, 4)),
		value: comp(cx, 1)
	};
}).filter(function(id) { return id.value; });

// The MRN keys the conditional update; fall back to the first identifier.
var mrn = identifiers.filter(function(id) { return id.type && id.type.coding && id.type.coding[0].code === 'MR'; })[0] || identifiers[0];
if (!mrn || !mrn.system) throw 'PID-3 has no identifier with an assigning authority to match the patient on';

// PID-5 patient name (XPN): 1 family, 2 given, 3 middle, 4 suffix, 5 prefix, 7 type.
var names = reps(pid['PID.5']).map(function(xpn) {
	return {
		use: NAME_USE[comp(xpn, 7)],
		family: comp(xpn, 1),
		given: [comp(xpn, 2), comp(xpn, 3)],
		prefix: [comp(xpn, 5)],
		suffix: [comp(xpn, 4)]
	};
});

// PID-11 address (XAD): 1-2 lines, 3 city, 4 state, 5 postal code, 6 country, 7 type.
var addresses = reps(pid['PID.11']).map(function(xad) {
	return {
		use: ADDRESS_USE[comp(xad, 7)],
		line: [comp(xad, 1), comp(xad, 2)],
		city: comp(xad, 3),
		state: comp(xad, 4),
		postalCode: comp(xad, 5),
		country: comp(xad, 6)
	};
});

// PID-13 home phone (XTN): 1 number, 2 use, 3 equipment type, 4 email.
var telecoms = reps(pid['PID.13']).map(function(xtn) {
	var equipment = comp(xtn, 3);
	var email = equipment === 'Internet' || equipment === 'X.400';
	return {
		system: email ? 'email' : 'phone',
		value: email ? comp(xtn, 4) : comp(xtn, 1),
		use: equipment === 'CP' ? 'mobile' : TELECOM_USE[comp(xtn, 2)]
	};
});

var patient = {
	resourceType: 'Patient',
	identifier: identifiers,
	name: names,
	telecom: telecoms,
	gender: GENDER[comp(pid['PID.8'], 1)],
	birthDate: fhirDate(comp(pid['PID.7'], 1)),
	address: addresses
};

// ---- PV1 -> Encounter -----------------------------------------------------------

var pv1 = msg['PV1'];

// PV1-19 visit number (CX).
var visitId = comp(pv1['PV1.19'], 1);
if (!visitId) throw 'PV1-19 (visit number) is empty; cannot match the encounter';
var visitIdentifier = {
	type: { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/v2-0203', code: 'VN' }] },
	system: systemFor(comp(pv1['PV1.19'], 4)) || VISIT_SYSTEM,
	value: visitId
};

var patientClass = comp(pv1['PV1.2'], 1);
var encounterClass = ENCOUNTER_CLASS[patientClass];

// PV1-3 assigned location (PL): 1 point of care, 2 room, 3 bed, 4 facility.
// Referenced by display name only for now; Location resources come later.
var pl = pv1['PV1.3'];
var locationName = [comp(pl, 1), comp(pl, 2), comp(pl, 3)].filter(Boolean).join(', ');

// PV1-7 attending doctor (XCN).
var attending = reps(pv1['PV1.7']).map(function(xcn) {
	return {
		type: [{ coding: [{ system: 'http://terminology.hl7.org/CodeSystem/v3-ParticipationType', code: 'ATND', display: 'attender' }] }],
		individual: xcnReference(xcn)
	};
});

var hospitalService = comp(pv1['PV1.10'], 1);

var patientRef = addEntry(patient, { method: 'PUT', url: conditionalUrl('Patient', mrn) });

var encounter = {
	resourceType: 'Encounter',
	identifier: [visitIdentifier],
	status: 'in-progress', // A01: the patient has been admitted
	'class': encounterClass
		? { system: 'http://terminology.hl7.org/CodeSystem/v3-ActCode', code: encounterClass.code, display: encounterClass.display }
		: { system: 'http://terminology.hl7.org/CodeSystem/v3-NullFlavor', code: 'UNK' },
	serviceType: hospitalService && { coding: [{ system: 'http://terminology.hl7.org/CodeSystem/v2-0069', code: hospitalService }] },
	subject: { reference: patientRef },
	participant: attending,
	period: { start: fhirDateTime(comp(pv1['PV1.44'], 1)) },
	location: locationName && [{ location: { display: locationName }, status: 'active' }]
};

var encounterRef = addEntry(encounter, { method: 'PUT', url: conditionalUrl('Encounter', visitIdentifier) });

// ---- MSH -> MessageHeader -------------------------------------------------------

var msh = msg['MSH'];
var sendingApp = msh['MSH.3'], sendingFacility = msh['MSH.4'];
var receivingApp = msh['MSH.5'], receivingFacility = msh['MSH.6'];
var messageType = [comp(msh['MSH.9'], 1), comp(msh['MSH.9'], 2), comp(msh['MSH.9'], 3)];
var messageTypeText = messageType.filter(Boolean).join('^'); // ADT^A01 (v2.3 has no MSG.3)
var messageTime = fhirDateTime(comp(msh['MSH.7'], 1));
var controlId = comp(msh['MSH.10'], 1);

// MSH-4 / MSH-6 facilities -> Organizations.
var senderRef = comp(sendingFacility, 1) && addOnce(hdOrganization(sendingFacility));
var receiverRef = comp(receivingFacility, 1) && addOnce(hdOrganization(receivingFacility));

var messageHeaderRef = addEntry({
	resourceType: 'MessageHeader',
	// MSH-11 processing ID (P production, T training, D debugging) and mode.
	meta: { tag: [
		comp(msh['MSH.11'], 1) && { system: 'http://terminology.hl7.org/CodeSystem/v2-0103', code: comp(msh['MSH.11'], 1) },
		comp(msh['MSH.11'], 2) && { system: 'http://terminology.hl7.org/CodeSystem/v2-0207', code: comp(msh['MSH.11'], 2) }
	] },
	// MSH-9 message type: the trigger event, from v2 table 0003.
	eventCoding: { system: 'http://terminology.hl7.org/CodeSystem/v2-0003', code: messageType[1], display: messageTypeText },
	// MSH-5 receiving application, MSH-6 receiving facility.
	destination: [setEndpoint({ name: comp(receivingApp, 1), receiver: receiverRef && { reference: receiverRef } }, receivingApp)],
	// MSH-4 sending facility.
	sender: senderRef && { reference: senderRef },
	// MSH-3 sending application.
	source: setEndpoint({ name: comp(sendingApp, 1), software: comp(sendingApp, 2) }, sendingApp),
	// What the message was about. Not in the IG's MSH map; added so the header
	// leads to the resources without going through Provenance.
	focus: [{ reference: patientRef }, { reference: encounterRef }]
}, { method: 'POST', url: 'MessageHeader' });

// ---- The original message ---------------------------------------------------------

// Kept verbatim (base64, segments separated by CR) so every resource can be
// traced back to exactly what the sender sent.
var originalRef = addEntry({
	resourceType: 'DocumentReference',
	status: 'current',
	description: messageTypeText + ' message ' + controlId + ' from ' + comp(sendingApp, 1),
	content: [{ attachment: { contentType: 'x-application/hl7-v2+er7', data: base64(connectorMessage.getRawData()) } }]
}, { method: 'POST', url: 'DocumentReference' });

var fromOriginal = [{ role: 'source', what: { reference: originalRef } }];
var converted = [{ reference: patientRef }, { reference: encounterRef }];

// ---- Provenance: where the message came from (MSH[Provenance-Source]) ------------

addEntry({
	resourceType: 'Provenance',
	target: converted,
	occurredDateTime: messageTime,
	recorded: messageTime,
	activity: { coding: [{ display: 'message - ' + messageTypeText }] },
	// MSH-4 sending facility authored the message (MSH-22 would win if sent).
	agent: [{
		type: { coding: [{ system: PARTICIPANT_TYPE, code: 'author' }] },
		who: senderRef ? { reference: senderRef } : { display: comp(sendingApp, 1) }
	}],
	entity: fromOriginal
}, { method: 'POST', url: 'Provenance' });

// ---- Provenance: this transformation (MSH[Provenance-Transformation]) -------------

var transformerRef = addOnce({
	resourceType: 'Device',
	identifier: [{ system: TRANSFORMER_SYSTEM, value: channelId }],
	deviceName: [{ name: 'Open Integration Engine channel "' + channelName + '"', type: 'user-friendly-name' }]
});

addEntry({
	resourceType: 'Provenance',
	target: converted.concat([{ reference: messageHeaderRef }]),
	recorded: new Date().toISOString(),
	activity: { coding: [{
		system: 'http://hl7.org/fhir/uv/v2mappings/CodeSystem/provenance-activity-type-v2-to-fhir',
		code: 'v2-fhir-transformation',
		display: 'V2 To FHIR Transformation'
	}] },
	agent: [{ type: { coding: [{ system: PARTICIPANT_TYPE, code: 'assembler' }] }, who: { reference: transformerRef } }],
	entity: fromOriginal
}, { method: 'POST', url: 'Provenance' });

// ---- Provenance: the event (EVN[Provenance]) ------------------------------------

var evn = msg['EVN'];
addEntry({
	resourceType: 'Provenance',
	target: [{ reference: messageHeaderRef }],
	// EVN-2 recorded date/time, EVN-6 event occurred.
	recorded: fhirDateTime(comp(evn['EVN.2'], 1)) || messageTime,
	occurredDateTime: fhirDateTime(comp(evn['EVN.6'], 1)),
	activity: { coding: [{ display: 'event - ' + messageTypeText }] },
	// EVN-5 operator; without one, the IG falls back to the sending facility.
	agent: [{
		who: comp(evn['EVN.5'], 1) ? xcnReference(evn['EVN.5'])
			: senderRef ? { reference: senderRef } : { display: comp(sendingApp, 1) }
	}]
}, { method: 'POST', url: 'Provenance' });

// ---- Bundle (MSH[Bundle]) ---------------------------------------------------------

var bundle = compact({
	resourceType: 'Bundle',
	// The IG maps a v2 message to a "message" Bundle in principle; here the engine
	// has already handled the event, so the result is stored as a transaction.
	type: 'transaction',
	identifier: { system: CONTROL_ID_SYSTEM, value: controlId },
	timestamp: messageTime,
	entry: entries
});

channelMap.put('fhirBundle', JSON.stringify(bundle, null, 2));

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;
